function refreshMinutes() {
  const n = Storage.get("refresh-minutes");
  return n === 5 || n === 15 ? n : 1;
}
async function reloadWidgets() {
  if (typeof Widget.reloadUserWidgets === "function") await Widget.reloadUserWidgets();
  else await Widget.reloadAll();
}

