// scripting/scripts/Calendar Timeline Scripting/timeline-view.tsx
function TimelineView({ model, width, height }) {
  const sx = width / model.width, sy = height / model.height;
  return <ZStack2 alignment="topLeading" frame={{ width, height }} clipped widgetBackground="#0A0A0B">
    <Link url="calshow://"><GraphView image={model.image} width={width} height={height} /></Link>
    {model.header.map((day3) => <Button
    key={day3.date}
    intent={SelectDay({ date: day3.date })}
    buttonStyle="plain"
    accessibilityLabel={`Mostrar ${day3.label}, ${day3.date}`}
    frame={{ width: day3.width * sx, height: day3.height * sy }}
    position={{ x: (day3.x + day3.width / 2) * sx, y: (day3.y + day3.height / 2) * sy }}
  >
      <Rectangle fill="black" opacity={1e-3} frame={{ width: day3.width * sx, height: day3.height * sy }} />
    </Button>)}
  </ZStack2>;
}

// scripting/scripts/Calendar Timeline Scripting/widget.tsx
async function main() {
  if (Widget3.family !== "systemMedium") {
    Widget3.present(<Text widgetBackground="#0A0A0B" foregroundStyle="white">Selecione o widget médio (4×2) para preservar a proporção original.</Text>);
    return;
  }
  try {
    const bridge = autoSynchronize({ origin: "widget", budgetMS: 8e3 });
    const model = await loadModel({ background: true }), { width, height } = Widget3.displaySize;
    await bridge;
    Storage.set("widget-diagnostic", { version: VERSION, phase: "present-requested", at: Date.now() });
    Widget3.present(
      <TimelineView model={model} width={width} height={height} />,
      { policy: "after", date: new Date(Date.now() + refreshMinutes() * 60 * 1e3) }
    );
  } catch (error) {
    const detail = failureDetails(error);
    try {
      Storage.set("widget-diagnostic", { version: VERSION, phase: "failed-before-present", at: Date.now(), error: detail });
    } catch {
    }
    Widget3.present(<Text widgetBackground="#0A0A0B" foregroundStyle="white">{detail.slice(0, 280)}. Abra o projeto no app para ver o diagnóstico.</Text>);
  }
}
Promise.resolve(main()).catch(__calendarBootFailure);

